// Portable address validation; no filesystem, environment or external imports.
export function isIP(value) {
  if (typeof value !== 'string' || value.length > 64) return 0;
  const ipv4 = text => {
    const octets = text.split('.');
    return octets.length === 4 && octets.every(part => /^(?:0|[1-9]\d{0,2})$/u.test(part) && Number(part) <= 255);
  };
  if (ipv4(value)) return 4;
  if (!value.includes(':') || value.includes('%') || /[^\da-f:.]/iu.test(value)) return 0;
  const compression = value.split('::');
  if (compression.length > 2) return 0;
  const groups = compression.flatMap(part => part ? part.split(':') : []);
  let count = 0;
  for (let i = 0; i < groups.length; i++) {
    const part = groups[i];
    if (part.includes('.')) {
      if (i !== groups.length - 1 || !ipv4(part)) return 0;
      count += 2;
    } else {
      if (!/^[\da-f]{1,4}$/iu.test(part)) return 0;
      count++;
    }
  }
  return compression.length === 2 ? (count < 8 ? 6 : 0) : (count === 8 ? 6 : 0);
}

// Conservative field-level redaction: retain no portion of a suspect value.
// These patterns are a precaution, not a guarantee for arbitrary real logs.
const secretLike = /\bBearer\s+\S+|\b(?:password|passwd|pwd|token|access_token|refresh_token|api[_-]?key|authorization|secret)\b["']?\s*[:=]|\b(?:sb_secret_|sk_)[A-Za-z0-9_-]+|\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/iu;

function safeText(value) {
  if (typeof value !== 'string') return null;
  return secretLike.test(value) ? '[REDACTED]' : value;
}

export function extractAlerts(fixture) {
  if (!fixture || fixture.schema !== 'aleph.xdr.fixture.v1'
      || fixture.moduleKey !== 'web-injection' || !Array.isArray(fixture.alerts)
      || fixture.alerts.some(alert => !alert || typeof alert !== 'object' || Array.isArray(alert))) {
    throw new Error('XDR_FIXTURE_INVALID');
  }
  return fixture.alerts.map(alert => ({
    timestamp: safeText(alert.timestamp),
    sourceAddress: safeText(alert.data?.srcip),
    account: safeText(alert.data?.srcuser),
    ruleLevel: Number.isFinite(alert.rule?.level) ? alert.rule.level : null,
    description: safeText(alert.rule?.description),
  }));
}



function countOf(value) {
  if (typeof value === 'string' && /^\d{1,6}$/u.test(value)) value = Number(value);
  return Number.isSafeInteger(value) && value > 0 ? value : null;
}

export function observe(alert) {
  const [row] = extractAlerts({ schema: 'aleph.xdr.fixture.v1', moduleKey: 'web-injection', alerts: [alert] });
  const readable = typeof row.description === 'string' && row.description !== '[REDACTED]' && row.description.length <= 2000;
  const text = readable ? row.description : '';
  const described = countOf(text.match(/(\d+)\s*(?:번|건)/u)?.[1]);
  const aggregated = countOf(alert.data?.count);
  const sqlEvidence = /SQL\s*(?:구문|표식)|데이터베이스 조회를 이어 붙/u.test(text);
  const scriptEvidence = /스크립트\s*(?:삽입 표기|표식)/u.test(text);
  const traversalEvidence = /경로(?:를 여러 단계 거슬러 올라가는| 이탈) 표기/u.test(text);
  const commandEvidence = /명령 구분자 표기/u.test(text);
  const suspicious = /SQL|sql|select|스크립트|따옴표|경로|주입|이상한|구분 문자|공격 표기|주소가 평소보다/u.test(text);
  const ordinary = /조회했습니다|화면이 열렸습니다|새로고침했습니다/u.test(text);
  return {
    readable,
    sourceAddress: row.sourceAddress,
    sameSourceConfirmed: Boolean(readable && isIP(row.sourceAddress ?? '')),
    count: described ?? aggregated,
    contradictoryCount: Boolean(described && aggregated && described !== aggregated),
    sqlEvidence, scriptEvidence, traversalEvidence, commandEvidence,
    // The classroom alert aggregates one source. Real ingest needs verified grouping.
    repetitionDenied: /반복은 없습니다|반복되지 않았/u.test(text),
    normal: readable && ordinary && !suspicious && !sqlEvidence && !scriptEvidence
      && !traversalEvidence && !commandEvidence && !(aggregated > 1),
  };
}

export function modelState(facts) {
  const { sourceAddress, ...state } = facts;
  return state;
}

